package models

// TrackPreviewImages contains the four static previews generated by the uploader.
type TrackPreviewImages struct {
	SquareDayURL      string `json:"square_day_url,omitempty" bson:"square_day_url,omitempty"`
	SquareNightURL    string `json:"square_night_url,omitempty" bson:"square_night_url,omitempty"`
	LandscapeDayURL   string `json:"landscape_day_url,omitempty" bson:"landscape_day_url,omitempty"`
	LandscapeNightURL string `json:"landscape_night_url,omitempty" bson:"landscape_night_url,omitempty"`
}

func (p TrackPreviewImages) Variant(variant string) string {
	switch variant {
	case "square_day":
		return p.SquareDayURL
	case "square_night":
		return p.SquareNightURL
	case "landscape_day":
		return p.LandscapeDayURL
	case "landscape_night":
		return p.LandscapeNightURL
	default:
		return ""
	}
}
